    def bubble_sort_with_cost(N, P):
        cost = 0
        operations = []
        for i in range(N):
            for j in range(0, N-i-1):
                if P[j] > P[j+1]:
                    P[j], P[j+1] = P[j+1], P[j]
                    cost += 1
                    operations.append((j+1, j+2))
        return cost, operations

    def solve_test_case(N, P):
        if P == list(range(1, N + 1)):
            return 0, 0, []
        else:
            return bubble_sort_with_cost(N, P)

    def solve_all(test_cases):
        results = []
        for N, P in test_cases:
            result = solve_test_case(N, P)
            results.append(result)
        return results

    test_cases = read_input()
    results = solve_all(test_cases)
    write_output(results)

